mapper.select:

where t.del_flag = '0'
and t.title like concat('%', #{name}, '%')
and t.publish_status = #{status}
and t.publish_status = #{publishStatus}
and t.guide_type = #{guideType}
and t.city_id = #{cityId}
and t.create_time >= #{beginCreateTime}
and t.create_time < #{endExclusive}
order by t.sort desc, t.id desc

where t.del_flag = '0' and t.publish_status = '1' and c.del_flag = '0' and c.status = '0' and p.del_flag = '0' and p.status = '0' and co.del_flag = '0' and co.status = '0' and t.city_id = #{cityId}
and (t.title like concat('%', #{keyword}, '%') or t.summary like concat('%', #{keyword}, '%') or t.content like concat('%', #{keyword}, '%'))
and t.guide_type = #{guideType}
order by coalesce(t.publish_time, t.create_time) desc, t.id desc order by t.view_count desc, t.like_count desc, t.id desc order by t.sort desc, t.view_count desc, coalesce(t.publish_time, t.create_time) desc, t.id desc
